{
  "labels": [
    {
      "i": 0,
      "speaker": "bot",
      "text": "Hello Amar आपको कौन सा product चाहिए please details बता दीजिए।"
    },
    {
      "i": 1,
      "speaker": "caller",
      "text": "मतलब product के बारे में बहुत जानकारी नहीं है बस वही turbine एक चाहिए।"
    },
    {
      "i": 2,
      "speaker": "bot",
      "text": "आपको जो बिजली बनाने या पानी के बहाव के लिए इस्तेमाल होने वाला turbine चाहिए वही product चाहिए ना?"
    },
    {
      "i": 3,
      "speaker": "caller",
      "text": "बिजली बना पानी के बहाव वाला नहीं चाहिए हवा से चलने वाला चाहिए।"
    },
    {
      "i": 4,
      "speaker": "bot",
      "text": "आपको जो हवा से बिजली बनाने वाला wind turbine चाहिए वही product चाहिए ना?"
    },
    {
      "i": 5,
      "speaker": "caller",
      "text": "जी।"
    },
    {
      "i": 6,
      "speaker": "bot",
      "text": "आप जिस seller को call कर रहे थे वो available नहीं है और मैं IndiaMART से बोल रही हूं।"
    },
    {
      "i": 7,
      "speaker": "bot",
      "text": "चलिए अब capacity के बारे में बात कर लेते हैं।"
    },
    {
      "i": 8,
      "speaker": "bot",
      "text": "आपको कौन सा चाहिए एक या दो या कुछ और?"
    },
    {
      "i": 9,
      "speaker": "caller",
      "text": "के बारे में।"
    },
    {
      "i": 10,
      "speaker": "caller",
      "text": "एक kilogram।"
    },
    {
      "i": 11,
      "speaker": "bot",
      "text": "ठीक है?"
    },
    {
      "i": 12,
      "speaker": "bot",
      "text": "अब बताइए turbine axis type में क्या prefer करेंगे?"
    },
    {
      "i": 13,
      "speaker": "bot",
      "text": "vertical axis, horizontal axis या कोई और?"
    },
    {
      "i": 14,
      "speaker": "caller",
      "text": "थोड़ा सा बताइए इसमें मैं थोड़ा confuse हूँ जानकारी नहीं हुआ कि kg क्या होता है वो क्या है।"
    },
    {
      "i": 15,
      "speaker": "bot",
      "text": "vertical axis turbine में पंख खड़े होते हैं जो किसी भी दिशा से आने वाली हवा से चल सकते हैं।"
    },
    {
      "i": 16,
      "speaker": "bot",
      "text": "आप क्या पसंद करेंगे?"
    },
    {
      "i": 17,
      "speaker": "caller",
      "text": "करेंगे।"
    },
    {
      "i": 18,
      "speaker": "caller",
      "text": "जी, बटी करनी चाहिए।"
    },
    {
      "i": 19,
      "speaker": "bot",
      "text": "बिल्कुल मैं note कर लेती हूं।"
    },
    {
      "i": 20,
      "speaker": "bot",
      "text": "आपको मैं seller details WhatsApp पे भेज दूंगी जिनसे आप details और price discuss कर सकते हैं।"
    },
    {
      "i": 21,
      "speaker": "caller",
      "text": "सुजीत जी।"
    },
    {
      "i": 22,
      "speaker": "bot",
      "text": "IndiaMART चुनने के लिए धन्यवाद।"
    },
    {
      "i": 23,
      "speaker": "bot",
      "text": "आपका दिन शुभ हो।"
    },
    {
      "i": 24,
      "speaker": "caller",
      "text": "Thank you."
    }
  ]
}
